#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    long n;
    std::cin >> n;
    std::vector<long> ones(17, 0);
    for (int i = 1; i < 17; ++i) {
        ones[i] = 10 * ones[i - 1] + 1;
    }
    // Recursive function equivalent
    std::function<long(const std::vector<long>&, long, int)> compute = [&](const std::vector<long>& ones, long n, int idx) -> long {
        long quotient = n / ones[idx];
        n %= ones[idx];
        long totalUsed = quotient * idx;
        if (n == 0) {
            return totalUsed;
        } else {
            long option1 = compute(ones, n, idx - 1);
            long option2 = idx + compute(ones, ones[idx] - n, idx - 1);
            return totalUsed + std::min(option1, option2);
        }
    };

    long result = compute(ones, n, 16);
    std::cout << result << std::endl;
    return 0;
}

